                                    var totQ = document.getElementById("tqty");
                                    var quant = document.getElementById("qty");
                                    var purchQ = document.getElementById("Nprices");
                                    var price = document.getElementById("price");

                                    var input = purchQ.value;
                                    var pQuant = parseInt(input.substring(0, input.indexOf("|")));
                                    totQ.value =  quant.value * pQuant;

                                    var priceHolder = "$ 0";
                                    var rawPurchQ = purchQ.options[purchQ.selectedIndex].text;
                                    if (rawPurchQ.includes("\(")) {
                                        priceHolder = rawPurchQ.substring(rawPurchQ.indexOf("$") +1, rawPurchQ.indexOf("\("));
                                    }
                                    else {
                                        priceHolder = rawPurchQ.substring(rawPurchQ.indexOf("$") + 1, rawPurchQ.indexOf("\/"));
                                    }
                                    price.value = "$ " + (parseFloat(priceHolder)* quant.value).toFixed(2);


                                  }




